mesSim(document.getElementById("sim-l25"),Object.assign({id:"l25"},{kind:"calc",title:"Một thời điểm, hai cách đọc giờ, gán ca",sub:"Giờ lưu trong CSDL là UTC; nhà máy ở Asia/Ho_Chi_Minh (UTC+7, không đổi giờ mùa hè).",
 inputs:[{k:"d",l:"Ngày (UTC)",opts:["11/11","12/11","13/11"],v:1},{k:"h",l:"Giờ UTC",min:0,max:23.5,step:0.5,v:19}],
 outputs:[{k:"utc",l:"Lưu trong CSDL (UTC)",f:V=>V.h,fmt:(v,V)=>(["11","12","13"][V.d])+"/11 "+String(Math.floor(v)).padStart(2,"0")+":"+(v%1?"30":"00")+"+00:00"},
  {k:"loc",l:"Giờ nhà máy",f:V=>V.h+7,fmt:(v,V)=>{const day=11+V.d+(v>=24?1:0);const h=v%24;return day+"/11 "+String(Math.floor(h)).padStart(2,"0")+":"+(h%1?"30":"00")+"+07:00"}},
  {k:"ca",l:"Ca và ngày sản xuất",big:1,f:V=>V.h+7,fmt:(v,V)=>{const day=11+V.d+(v>=24?1:0);const h=v%24;if(h>=6&&h<14)return"Ca 1 · ngày "+day+"/11";if(h>=14&&h<22)return"Ca 2 · ngày "+day+"/11";return"Ca 3 · ngày "+(h<6?day-1:day)+"/11"}}],
 tasks:[{t:"Thời điểm 19:00 UTC ngày 12/11 là mấy giờ ở nhà máy, thuộc ca nào?",ok:"02:00 ngày 13/11 giờ nhà máy, nhưng thuộc ca 3 của ngày sản xuất 12/11 (ca bắt đầu 22:00 ngày 12).",check:s=>s.V.d===1&&s.V.h===19},
  {t:"Tìm thời điểm UTC đúng lúc bắt đầu ca 1 ngày 12/11 (06:00 giờ nhà máy).",ok:"23:00 UTC ngày 11/11: cùng một thời điểm, hai cách viết.",check:s=>s.V.d===0&&s.V.h===23},
  {t:"Tìm một thời điểm UTC thuộc ca 2.",check:s=>{const h=(s.V.h+7)%24;return h>=14&&h<22}}]}));

